parameters.jsonBody:
={
  "model": "gpt-4o-mini",
  "response_format": { "type": "json_object" },
  "messages": [
    {
      "role": "system",
      "content": "You are an expert customer support routing assistant. Detect the primary language of the customer support ticket. Output a single JSON object matching this format: { \"languageCode\": \"two-letter ISO code\", \"languageName\": \"English name of language\", \"isCodeMixed\": true/false, \"confidence\": 1.0 }. Allowed ISO codes: en, hi, bn, te, mr, ta, gu, ur, kn, ml, pa, or, as. For Romanized Hindi/Hinglish or code-mixed input, set languageCode to 'hi' and isCodeMixed to true."
    },
    {
      "role": "user",
      "content": "{{ $json.ticketText }}"
    }
  ],
  "max_tokens": 100,
  "temperature": 0
}

parameters.jsCode:
const response = $json;

// 1. Check for API-level call failures (timeouts, network errors, auth issues)
if (response.error || !response.choices || response.choices.length === 0) {
  return {
    json: {
      languageCode: "en",
      languageName: "English",
      isCodeMixed: false,
      confidence: 0.0,
      error: true,
      errorMessage: response.error?.message || "API response structure was missing choices object."
    }
  };
}

// 2. Parse text content from response
let responseText = "";
try {
  responseText = response.choices[0].message.content.trim();
} catch (e) {
  return {
    json: {
      languageCode: "en",
      languageName: "English",
      isCodeMixed: false,
      confidence: 0.0,
      error: true,
      errorMessage: "Failed to extract content field from API structure: " + e.message
    }
  };
}

// 3. Parse content string as JSON
let result;
try {
  result = JSON.parse(responseText);
} catch (e) {
  return {
    json: {
      languageCode: "en",
      languageName: "English",
      isCodeMixed: false,
      confidence: 0.0,
      error: true,
      errorMessage: "Model output was not valid JSON: " + e.message + ". Output text: " + responseText
    }
  };
}

// 4. Validate output and enforce English fallback for unhandled tags
const allowedCodes = ["en", "hi", "bn", "te", "mr", "ta", "gu", "ur", "kn", "ml", "pa", "or", "as"];
let finalCode = (result.languageCode || "en").toLowerCase().trim();
let finalName = result.languageName || "English";

if (!allowedCodes.includes(finalCode)) {
  finalCode = "en";
  finalName = "English";
}

return {
  json: {
    languageCode: finalCode,
    languageName: finalName,
    isCodeMixed: !!result.isCodeMixed,
    confidence: Number(result.confidence) || 0.0,
    error: false,
    errorMessage: ""
  }
};
